// Loads the gource-web WebAssembly module generated by scripts/build-web.sh
// into src/wasm/. import.meta.glob resolves to an empty map when the bindings
// have not been built, so `vite build` works without them and the page can
// say what is missing instead of failing to bundle.

import type { EngineFactory, GourceWasmModule } from './types';

const modules = import.meta.glob('../wasm/gource_web.js');
const MODULE_PATH = '../wasm/gource_web.js';

export class EngineMissingError extends Error {
  constructor() {
    super(
      'The WebAssembly engine has not been built. Run scripts/build-web.sh to generate packages/viewer/src/wasm/, ' +
        'or open the page with ?mock=1 to use the placeholder engine.',
    );
    this.name = 'EngineMissingError';
  }
}

export function wasmAvailable(): boolean {
  return MODULE_PATH in modules;
}

let wasmPromise: Promise<GourceWasmModule> | null = null;

/** Imports and initialises the wasm module once per realm (page or worker). */
export function loadWasm(): Promise<GourceWasmModule> {
  if (!wasmPromise) {
    const loader = modules[MODULE_PATH];
    if (!loader) return Promise.reject(new EngineMissingError());
    wasmPromise = (async () => {
      const mod = (await loader()) as GourceWasmModule;
      await mod.default();
      return mod;
    })();
    wasmPromise.catch(() => {
      wasmPromise = null;
    });
  }
  return wasmPromise;
}

export async function loadEngine(mock: boolean): Promise<EngineFactory> {
  if (mock) {
    const { MockEngine } = await import('./mock');
    return { kind: 'mock', createApp: (canvas) => new MockEngine(canvas) };
  }
  const mod = await loadWasm();
  return { kind: 'wasm', createApp: (canvas) => new mod.GourceApp(canvas) };
}
